(function(D){D.industries=[{"slug":"ecommerce","name":"E-commerce & D2C","h":"GET FOUND. GET CHOSEN. GET BOUGHT AGAIN.","challenges":["Discovery in crowded categories","Product and category findability","Product-page confidence (reviews, details, trust)","Cart and checkout friction","Retention and repeat purchase"],"behaviour":"Shoppers compare quickly, trust specifics, abandon slow checkouts and return when the experience was easy.","approach":"Diagnose the funnel from first visit to repeat order, fix the biggest leak first, then grow demand with paid and organic search together.","channels":["Meta Ads","Google Shopping & Search","E-commerce SEO","Email/WhatsApp retention"],"kpis":["Conversion rate","Cost per acquisition","Average order value","Repeat purchase rate"],"services":["ecommerce-seo","meta-ads","cro","marketing-automation"]},{"slug":"healthcare","name":"Healthcare & Wellness","h":"BE THE PRACTICE PEOPLE TRUST: AND FIND.","note":"Applicable healthcare advertising rules, platform policies and patient-privacy requirements must be checked before any campaign launches. FODO never promises clinical outcomes or makes unsupported medical claims.","challenges":["Local discovery and trust","Appointment requests that get lost","Educational content that stays compliant","Cautious claims and privacy obligations"],"behaviour":"Patients search locally, read reviews, compare credentials and want a simple way to book or ask.","approach":"Accurate local presence, clear service pages, careful educational content and a follow-up process that respects privacy.","channels":["Local SEO","Google Search Ads (policy-checked)","Educational content","Appointment follow-up automation"],"kpis":["Appointment requests","Call and direction requests","Review volume and response","Page-to-enquiry rate"],"services":["local-seo","content-marketing","web-design","marketing-automation"]},{"slug":"real-estate","name":"Real Estate","h":"FEWER TYRE-KICKERS. MORE SERIOUS BUYERS.","challenges":["Lead quality over lead volume","Location and project pages that convert","Enquiry funnels that leak","Sales follow-up over long cycles"],"behaviour":"Buyers research for months, shortlist by location and budget, and respond to fast, specific follow-up.","approach":"Qualify in the funnel, build location-specific pages, align ads with budget and intent, and automate follow-up without losing the human touch.","channels":["Google Search","Meta lead campaigns","Location SEO","CRM + WhatsApp follow-up"],"kpis":["Qualified lead rate","Cost per site visit booked","Follow-up speed","Lead-to-visit conversion"],"services":["google-ads","landing-pages","marketing-automation","local-seo"]},{"slug":"startups","name":"Startups","h":"TEST FAST. LEARN FASTER. SPEND WISELY.","challenges":["Audience validation","Lean experiments with small budgets","Go-to-market sequencing","Learning velocity"],"behaviour":"Early customers are curious but sceptical; clear positioning and proof beat polish.","approach":"Prioritise one audience and one message, run small structured tests, and invest only where evidence appears.","channels":["Landing-page tests","Targeted paid tests","Founder-led content","Email/WhatsApp nurture"],"kpis":["Cost per qualified signup","Message test win rate","Activation rate","Learning per rupee spent"],"services":["brand-strategy","landing-pages","paid-advertising","analytics"]},{"slug":"saas","name":"SaaS","h":"TURN PAIN POINTS INTO PIPELINE.","challenges":["Pain-point messaging","Trial and demo acquisition","Funnel conversion from visit to activation","Lifecycle content","Pipeline quality"],"behaviour":"Buyers compare features, read documentation, want proof and prefer trying before talking.","approach":"Intent-led search, decision-maker targeting on LinkedIn, lifecycle content and measurement from first visit to retained account.","channels":["Google Search","LinkedIn Ads","SEO & content","Lifecycle automation"],"kpis":["Trial/demo conversion rate","Cost per qualified pipeline","Activation rate","Content-assisted pipeline"],"services":["linkedin-ads","seo","marketing-automation","cro"]},{"slug":"local-business","name":"Local Business","h":"WHEN THEY SEARCH NEARBY, BE THE ANSWER.","challenges":["Local search visibility","Accurate business details everywhere","Calls and messages that get answered","Reputation management","Location-specific landing pages"],"behaviour":"People search with intent to visit or call today; proximity, reviews and clear hours decide.","approach":"Fix the basics first, profile, details, reviews, then add local pages and targeted ads where demand exists.","channels":["Google Business Profile","Local SEO","Local search ads","Instagram"],"kpis":["Calls and direction requests","Map-pack visibility","Review rating and volume","Enquiry response time"],"services":["local-seo","google-ads","social-media","web-design"]},{"slug":"personal-brands","name":"Personal Brands","h":"BE KNOWN FOR SOMETHING SPECIFIC.","challenges":["Positioning","Content pillars","Credibility and audience trust","Consistent distribution","Lead capture"],"behaviour":"Audiences follow people who are consistent, specific and useful, and buy when trust meets a clear offer.","approach":"Define one position, build three to four content pillars, distribute consistently and capture interest with a simple offer.","channels":["LinkedIn","Instagram / short-form","Newsletter","Landing page"],"kpis":["Profile visits to link clicks","Newsletter growth","Enquiries per month","Content consistency"],"services":["brand-strategy","short-form-content","content-marketing","landing-pages"]}];D.pillars=[{"id":"paid","name":"Paid Media","first":"paid-advertising"},{"id":"seo","name":"SEO","first":"seo"},{"id":"content","name":"Content","first":"content-marketing"},{"id":"social","name":"Social","first":"social-media"},{"id":"brand","name":"Brand","first":"brand-strategy"},{"id":"automation","name":"Automation","first":"marketing-automation"},{"id":"web","name":"Web & CRO","first":"web-design"}];D.services=[{"slug":"paid-advertising","pillar":"paid","name":"Paid Advertising","h":"BUY ATTENTION. TURN IT INTO GROWTH.","problem":"Many accounts grow spend before they grow structure: mixed objectives in one campaign, audiences overlapping, and no clear link between a click and a business result.","do":["Account and campaign structure built around one objective per campaign","Audience strategy: prospecting, warm and retargeting layers where they make sense","Creative testing plan with clear hypotheses","Landing-page alignment so the ad promise matches the page","Budgets always controlled and approved by you","Conversion measurement set up before spend starts"],"track":["Cost per lead / acquisition","Conversion rate by audience and creative","Lead quality feedback from your sales team","Spend pacing vs. agreed budget"],"channels":["Meta","Google","LinkedIn","TikTok"],"deliv":["Account audit & restructure plan","Campaign build","Monthly creative test log","Reporting dashboard"],"who":"Businesses already spending (or ready to spend) on ads who want decisions based on evidence, not platform suggestions.","outcomes":"Clearer cost per result, less wasted spend, and a learning loop you can keep running.","faqs":[["Who controls the ad budget?","You do. Spend is paid from your ad accounts; FODO plans and manages within the limit you approve."],["Do you guarantee a cost per lead?","No. We agree targets and report honestly against them; outcomes depend on offer, market and landing experience."],["How long before results show?","Early signals typically appear within the first few weeks of testing; a stable read needs more data. We never promise a timeline."],["Which platform should I start with?","The one where your buyers already look for you. Discovery decides this, not a default."]],"related":["meta-ads","google-ads","landing-pages","analytics"]},{"slug":"meta-ads","pillar":"paid","name":"Meta Ads","h":"WHERE YOUR CUSTOMERS SCROLL. BE THERE.","problem":"Boosted posts, one audience, one creative, then the cost rises and nobody knows why. Creative fatigue and weak tracking quietly eat the budget.","do":["Facebook and Instagram placement strategy","Prospecting audiences built from interests, lookalikes and broad targeting tests","Retargeting only where the funnel supports it","Creative testing: hooks, formats, angles","Pixel / Conversions API tracking review","Creative fatigue monitoring and refresh cadence"],"track":["Cost per result","Click-through and hook rate","Frequency and fatigue signals","Purchase or lead conversion rate"],"channels":["Facebook","Instagram","Messenger","Audience Network (optional)"],"deliv":["Audience map","Creative test matrix","Campaign build","Weekly performance notes"],"who":"D2C brands, local services, lifestyle and hospitality businesses whose customers discover visually.","outcomes":"Better creative learning, controlled frequency, and spend aimed at people likely to act.","faqs":[["Do you make the creatives?","We write concepts, hooks and copy. Design and video production are scoped separately in discovery."],["Is retargeting always needed?","No. Small audiences and short sales cycles sometimes do not justify it; we test before committing budget."],["What about iOS tracking limits?","We set up server-side tracking where possible and read results with that limitation in mind."],["Can you work in my existing ad account?","Yes, we prefer it. Your data stays yours."]],"related":["paid-advertising","short-form-content","landing-pages","cro"]},{"slug":"google-ads","pillar":"paid","name":"Google Ads","h":"BE THE ANSWER WHEN THEY SEARCH.","problem":"Broad match everything, no negative keywords, and a homepage as the landing page. Intent is the most valuable thing in Google Ads, and the easiest to waste.","do":["Search campaigns built around intent clusters","Keyword and negative-keyword structure maintained weekly","Display and YouTube only when the objective calls for them","Ad copy matched to query and landing page","Conversion tracking and call tracking review","Budget pacing and bid strategy decisions explained in plain language"],"track":["Cost per conversion","Search impression share on priority terms","Quality signals (relevance, landing experience)","Wasted-spend share from irrelevant queries"],"channels":["Google Search","Performance Max (cautiously)","YouTube","Display"],"deliv":["Keyword & intent map","Negative keyword library","Campaign build","Search-term review log"],"who":"Businesses with existing demand: people already search for what they sell.","outcomes":"Spend concentrated on high-intent queries and pages that answer them.","faqs":[["Should I use Performance Max?","Sometimes. It needs strong conversion data and clear exclusions; we test it alongside Search, not instead of it."],["Why do my clicks not convert?","Often the landing page, not the ad. We review both together."],["Do you claim Google Partner status?","No. FODO makes no partnership claims it cannot show."],["How often do you review search terms?","Weekly during active optimisation."]],"related":["paid-advertising","landing-pages","seo","analytics"]},{"slug":"linkedin-ads","pillar":"paid","name":"LinkedIn Ads","h":"REACH DECISION-MAKERS, NOT JUST CLICKS.","problem":"LinkedIn costs more per click than most platforms. Treating it like Meta, broad audiences, no offer, burns budget fast.","do":["Decision-maker targeting by role, seniority, company size and industry","Offer design for longer B2B cycles (guides, demos, assessments)","Lead Gen Forms vs. landing-page tests","Lead quality scoring with your sales team","Retargeting website visitors and engagers","Cost awareness built into every recommendation"],"track":["Cost per qualified lead (not just lead)","Meeting or demo rate","Audience overlap and frequency","Pipeline feedback from sales"],"channels":["LinkedIn Sponsored Content","Message Ads","Lead Gen Forms"],"deliv":["ICP & audience plan","Offer brief","Campaign build","Lead quality report"],"who":"B2B, SaaS, consulting and professional services with a defined buyer profile.","outcomes":"Fewer, better leads and clearer feedback from sales to marketing.","faqs":[["Is LinkedIn too expensive for small budgets?","It can be. We advise honestly if your budget would be better used elsewhere."],["Lead Gen Forms or landing pages?","Forms lower friction; pages qualify better. We often test both."],["How do you judge lead quality?","Through a simple scoring sheet agreed with your sales team."],["How long are B2B cycles?","Often weeks to months, reporting reflects that instead of chasing weekly conversions."]],"related":["paid-advertising","copywriting","marketing-automation","analytics"]},{"slug":"tiktok-ads","pillar":"paid","name":"TikTok Ads","h":"SHORT VIDEOS. LONG MEMORY.","problem":"Polished brand ads feel out of place on TikTok. Without native-feeling creative and fast hook testing, spend buys views that never become customers.","do":["Short-form creative concepts and scripts","Hook testing across the first 1–3 seconds","Native-feeling formats (UGC-style, voiceover, text-on-screen)","Landing-page alignment for mobile-first visitors","Spark Ads where creator content exists","Clear scope: FODO plans and scripts; footage production is agreed separately"],"track":["Hook rate and watch-through","Cost per click / result","Conversion rate on mobile landing pages","Creative win rate"],"channels":["TikTok In-Feed","Spark Ads"],"deliv":["Creative concept deck","Script library","Campaign build","Creative performance log"],"who":"Consumer brands with a visual product or a story that fits short video.","outcomes":"A repeatable way to find hooks that work, before scaling spend.","faqs":[["Do you shoot the videos?","Not by default. We script and direct concepts; production is scoped with you or a creator."],["Is TikTok right for B2B?","Rarely the first choice. We will say so."],["How many creatives do we need?","Enough to test, usually several variations per concept at launch."],["Can we reuse Instagram Reels?","Often yes, with adjustments to hooks and captions."]],"related":["short-form-content","meta-ads","influencer-marketing","landing-pages"]},{"slug":"seo","pillar":"seo","name":"SEO","h":"BE FOUND BEFORE YOU'RE NEEDED.","problem":"Rankings for your brand name, nothing for the problems you solve. Technical issues block crawling and content is written for nobody in particular.","do":["Technical audit: crawlability, indexing, speed, structure","On-page optimisation matched to search intent","Content plan that answers real questions","Internal linking architecture","Ethical off-page approach, no bought links","Transparent monthly reporting"],"track":["Non-brand organic visibility","Indexed pages and technical health","Organic leads or sales, not just sessions","Priority keyword movement"],"channels":["Google Search","Bing","AI-powered search surfaces"],"deliv":["Technical audit","Keyword & intent map","Content briefs","Monthly SEO report"],"who":"Businesses that want durable, compounding demand rather than rented attention.","outcomes":"Visibility for the searches that matter, on pages built to convert.","faqs":[["How long does SEO take?","Months, not days. We set expectations in discovery and show progress along the way."],["Do you guarantee rankings?","No one honestly can. We commit to the work and the reporting."],["Will you write the content?","We can brief, write, or edit, scope is agreed per project."],["Do you buy links?","No."]],"related":["local-seo","ecommerce-seo","content-marketing","web-design"]},{"slug":"local-seo","pillar":"seo","name":"Local SEO","h":"OWN YOUR NEIGHBOURHOOD ON GOOGLE.","problem":"Inconsistent address details, an unmanaged Google Business Profile, and no process for reviews. Nearby customers find a competitor instead.","do":["Google Business Profile setup and guidance","Accurate, consistent business details everywhere","Location-specific landing pages","Review request and response process","Local content and citations","Tracking of calls, directions and messages"],"track":["Profile views, calls and direction requests","Map-pack visibility for priority terms","Review volume and response time","Local landing-page conversions"],"channels":["Google Business Profile","Google Maps","Local directories"],"deliv":["Profile optimisation","Location page templates","Review process guide","Monthly local report"],"who":"Clinics, restaurants, salons, showrooms, agencies, any business people visit or call.","outcomes":"More of the right local enquiries from people ready to act.","faqs":[["Can you guarantee a map-pack position?","No. We improve the signals Google uses and report what changes."],["Do you write fake reviews?","Never. We help you ask real customers properly."],["Multiple branches?","Yes, each gets its own accurate profile and page."],["How do we track calls?","Through profile insights and, where appropriate, call tracking."]],"related":["seo","web-design","analytics","social-media"]},{"slug":"ecommerce-seo","pillar":"seo","name":"E-commerce SEO","h":"TURN SEARCHES INTO CARTS.","problem":"Thousands of product pages, thin descriptions, duplicate category URLs and filters that create crawl chaos. Shoppers search; your store is not in the results.","do":["Category and product URL structure review","Collection-page optimisation for commercial intent","Product content guidelines that help buyers decide","Faceted navigation and duplicate control","Internal linking from content to categories","Technical health monitoring"],"track":["Organic revenue and assisted conversions","Category-page visibility","Indexation vs. crawl waste","Product-page conversion rate from search"],"channels":["Google Search","Google Shopping (organic listings)","Merchant Center"],"deliv":["Store technical audit","Category keyword map","Product content guide","Quarterly roadmap"],"who":"Online stores on Shopify, WooCommerce or custom platforms with a real catalogue.","outcomes":"Category pages that rank for buying terms and product pages that help people decide.","faqs":[["Which platform do you work with?","Any: Shopify, WooCommerce, Magento, custom."],["Do you fix technical issues yourselves?","We specify them clearly; implementation is by your developer or ours, as scoped."],["Is Shopping ads SEO?","No, that is paid. Organic Shopping listings via Merchant Center are covered."],["How many products can you optimise?","We prioritise by revenue potential rather than doing everything at once."]],"related":["seo","cro","google-ads","analytics"]},{"slug":"content-marketing","pillar":"content","name":"Content Marketing","h":"CONTENT THAT EARNS ATTENTION.","problem":"Publishing for the calendar, not the customer. Posts go out; questions stay unanswered; nothing connects to a sale.","do":["Content strategy tied to business goals","Audience question research","Editorial calendar with owners and formats","Distribution plan, content does not promote itself","Measurement framework beyond views","Repurposing system across channels"],"track":["Content-assisted leads and conversions","Engaged time and return visits","Search visibility of content","Share of content that is reused"],"channels":["Website / blog","Email","LinkedIn","Instagram","YouTube (as scoped)"],"deliv":["Content strategy","Editorial calendar","Briefs & drafts","Monthly content report"],"who":"Brands that want to be trusted before they are chosen.","outcomes":"A library of useful material that keeps working after it is published.","faqs":[["How much content do we need?","Less than you think, done better. Discovery sets a sustainable cadence."],["Do you write it?","We can, or we brief your team, your choice."],["How do you measure content?","By what it helps cause: enquiries, trials, assisted sales, not just views."],["Do you use AI tools?","Where they help with drafts and research; everything is edited by a human and checked for accuracy."]],"related":["copywriting","seo","social-media","short-form-content"]},{"slug":"copywriting","pillar":"content","name":"Copywriting","h":"WORDS THAT MAKE PEOPLE ACT.","problem":"Clever headlines that say nothing. Features listed, benefits missing. Calls to action that ask for nothing in particular.","do":["Message hierarchy: what to say first, second, last","Hooks and headlines for ads and pages","Offer framing and objection handling","Landing page, email and ad copy","Clear calls to action","Message testing so copy decisions use evidence"],"track":["Click-through on headlines and hooks","Landing-page conversion rate","Email reply and click rate","Variant win rate in tests"],"channels":["Ads","Landing pages","Email","Website","WhatsApp scripts"],"deliv":["Messaging guide","Copy decks","Variant sets for testing","Copy review notes"],"who":"Anyone whose words have to carry the sale, founders, D2C brands, B2B teams.","outcomes":"Copy that is clearer, more specific and easier to act on.","faqs":[["Do you write in Hindi or Hinglish?","Yes, where it fits your audience."],["How many revisions?","Agreed per project; we aim for alignment early with a messaging guide."],["Can you fix our existing pages?","Yes, copy audits are a common starting point."],["Do you write long-form?","Yes, including articles, guides and case-study drafts."]],"related":["landing-pages","content-marketing","brand-strategy","cro"]},{"slug":"social-media","pillar":"social","name":"Social Media Management","h":"SHOW UP. STAND OUT. STAY CONSISTENT.","problem":"Posting when there is time, going quiet when there is not. No platform strategy, no voice, no idea what any of it is for.","do":["Platform strategy, where to be and why","Content pillars tied to business goals","Publishing calendar with approvals","Community response process","Monthly reporting on what moved","Content-production scope clarified in discovery"],"track":["Reach and saves on priority content","Profile visits to website clicks","Response time to messages","Enquiries attributed to social"],"channels":["Instagram","LinkedIn","Facebook","YouTube / TikTok (as scoped)"],"deliv":["Social strategy","Monthly calendar","Caption & creative briefs","Monthly report"],"who":"Brands that want consistency and purpose, not just presence.","outcomes":"A recognisable presence that sends people somewhere useful.","faqs":[["Do you design the posts?","Design and video production are scoped separately; strategy, calendar and captions are included."],["How many posts per week?","As many as you can sustain with quality, set in discovery."],["Do you reply to comments and DMs?","We set the process and can manage it within agreed hours."],["Can you grow followers?","We focus on the right audience and actions, not follower counts."]],"related":["short-form-content","content-marketing","influencer-marketing","brand-identity"]},{"slug":"short-form-content","pillar":"social","name":"Short-Form Content Strategy","h":"15 SECONDS TO EARN A FOLLOW.","problem":"Reels made without a hook, a point or a next step. Effort goes in; nothing memorable comes out.","do":["Hook frameworks for the first three seconds","Story structures that fit 15–60 seconds","Scripting and shot lists","Editing guidance (edits only when agreed in scope)","Testing and repurposing across Reels, Shorts and TikTok","Honest scope: no footage is implied, we plan what you or a creator will shoot"],"track":["Hook retention","Completion rate","Saves, shares and profile visits","Conversions from pinned or linked content"],"channels":["Instagram Reels","YouTube Shorts","TikTok"],"deliv":["Hook library","Script bank","Shot list templates","Performance review"],"who":"Founders, D2C and lifestyle brands, educators and personal brands.","outcomes":"A repeatable system for making short videos that earn attention and action.","faqs":[["Do you film?","Not by default. We script and direct; filming is by you, your team or a creator we help brief."],["Do we need to show our face?","No, voiceover, text and product formats work too."],["How often should we post?","Consistency beats volume; we set a pace you can keep."],["Can old videos be reused?","Often, with new hooks and captions."]],"related":["social-media","tiktok-ads","meta-ads","copywriting"]},{"slug":"influencer-marketing","pillar":"social","name":"Influencer Marketing","h":"BORROW TRUST. EARN IT BACK.","problem":"Paying for follower counts instead of fit. No brief, no usage rights, no tracking, just a post and a hope.","do":["Creator fit assessment based on audience, not vanity numbers","Outreach workflow and negotiation support","Clear briefs with do's and don'ts","Deliverables, usage rights and approvals documented","Tracking links and codes","Reporting on what each collaboration produced"],"track":["Engaged reach within your target audience","Traffic and conversions per creator","Content reuse value","Cost per result vs. other channels"],"channels":["Instagram","YouTube","LinkedIn (B2B creators)"],"deliv":["Creator shortlist (built per project, no pre-made roster)","Brief template","Agreement checklist","Campaign report"],"who":"Consumer brands and B2B teams that want third-party credibility.","outcomes":"Collaborations that are chosen, briefed and measured properly.","faqs":[["Do you have a creator roster?","No fixed roster. We shortlist for each brief so the fit is real."],["Who pays the creator?","You do, directly or via an agreed process; we support negotiation."],["Micro or macro?","Usually micro and mid for fit and cost; we recommend per objective."],["How is it tracked?","Links, codes and agreed reporting windows."]],"related":["social-media","short-form-content","brand-strategy","analytics"]},{"slug":"brand-strategy","pillar":"brand","name":"Brand Strategy","h":"KNOW WHO YOU ARE BEFORE THEY ASK.","problem":"Every channel says something slightly different. Pricing says premium; copy says cheap; the team cannot explain why you are different in one sentence.","do":["Audience and competitor understanding","Positioning and promise","Differentiators that are true and provable","Voice and tone guidelines","Message hierarchy for every touchpoint","Go-to-market priorities"],"track":["Message consistency across channels","Clarity tests with real prospects","Conversion impact of repositioned pages","Sales team adoption"],"channels":["All owned, earned and paid touchpoints"],"deliv":["Brand strategy document","Messaging framework","Voice guide","Launch priorities"],"who":"Founders launching, repositioning or scaling past word-of-mouth.","outcomes":"One clear story the whole business can tell consistently.","faqs":[["How long does it take?","Typically a few weeks of workshops and refinement, set in discovery."],["Is this just a logo?","No. Identity comes after strategy; see Brand Identity."],["Do you interview customers?","Where possible, yes, it is the fastest route to truth."],["Will it change our pricing?","It may inform it; positioning and pricing should agree."]],"related":["brand-identity","copywriting","web-design","content-marketing"]},{"slug":"brand-identity","pillar":"brand","name":"Brand Identity","h":"LOOK LIKE YOU MEAN IT.","problem":"A logo from years ago, three fonts, colours chosen per post. The brand looks different every time someone meets it.","do":["Identity system: logo usage, typography, palette","Digital-first components for social, web and ads","Usage principles so the team stays consistent","Templates for recurring formats","Accessibility-aware colour choices","Handover kit for designers and freelancers"],"track":["Consistency across live touchpoints","Time saved producing assets","Recognition in audience feedback"],"channels":["Web","Social","Ads","Print (as scoped)"],"deliv":["Identity guidelines","Asset kit","Templates","Handover session"],"who":"Businesses whose visuals have fallen behind their ambition.","outcomes":"A coherent, recognisable look that is easy to apply.","faqs":[["Do you redesign logos?","Yes, or refine the existing mark where it still works."],["Do you claim design awards?","No awards or certifications are claimed anywhere on this site."],["Which tools do you deliver in?","Figma or Canva templates depending on your team."],["Can we keep our current colours?","Often yes, we make them work harder."]],"related":["brand-strategy","web-design","social-media","landing-pages"]},{"slug":"web-design","pillar":"web","name":"Web Design","h":"A WEBSITE THAT WORKS AS HARD AS YOU DO.","problem":"A beautiful site nobody can navigate, or a functional one nobody trusts. Slow, confusing and silent about what to do next.","do":["Responsive information architecture","Content hierarchy that guides the visitor","Conversion paths on every key page","Accessibility and performance built in","Analytics and tracking set up at launch","Technical handover and documentation"],"track":["Core conversions (enquiries, calls, purchases)","Page speed and accessibility scores","Key-page engagement","Form completion rate"],"channels":["WordPress","Shopify","Webflow","Custom static or framework builds"],"deliv":["Sitemap & wireframes","Design system","Built site","Handover docs"],"who":"Businesses whose website is the first meeting with most customers.","outcomes":"A site that is fast, clear, trustworthy and measurable.","faqs":[["Which platform do you recommend?","Depends on content, commerce and team, decided in discovery."],["Do you host the site?","We help choose hosting; you own the accounts."],["Will it be accessible?","We target WCAG AA practices as standard."],["Do you provide copy?","Yes, via Copywriting; it is scoped alongside design."]],"related":["landing-pages","cro","seo","brand-identity"]},{"slug":"landing-pages","pillar":"web","name":"Landing Pages","h":"ONE PAGE. ONE JOB.","problem":"Ads sent to the homepage. Five calls to action. A form asking for twelve fields. The click was earned; the page lost it.","do":["Message match between ad and page","One clear goal per page","Friction reduction in layout and form design","Trust elements that are true and specific","Event tracking for every meaningful action","Variant setup for testing"],"track":["Conversion rate","Form start vs. completion","Scroll depth to key sections","Cost per conversion impact"],"channels":["Paid search","Paid social","Email","QR / offline campaigns"],"deliv":["Page wireframe","Copy","Built page","Tracking plan"],"who":"Anyone running campaigns that deserve a focused destination.","outcomes":"More of the clicks you pay for turn into enquiries or sales.","faqs":[["Can it be built on our site?","Yes, or on a dedicated page builder if faster."],["How many fields should a form have?","As few as you need to follow up well."],["Do you A/B test?","When traffic supports it; otherwise we iterate on evidence."],["How fast can one be live?","Often within days once copy and offer are agreed."]],"related":["cro","copywriting","paid-advertising","analytics"]},{"slug":"cro","pillar":"web","name":"Conversion Rate Optimisation","h":"YOUR ADS AREN'T THE PROBLEM. YOUR FUNNEL MIGHT BE.","problem":"Traffic grows, conversions do not. Decisions are made on opinion, and 'tests' end before anything is learned.","do":["Analytics review to find where people leave","Hypotheses ranked by impact and effort","UX friction review on key pages and forms","Experiments where traffic allows; structured iterations where it does not","Clear measurement plans before any change","Honest reporting: no significance claimed without the data"],"track":["Step-by-step funnel conversion","Form abandonment points","Revenue or leads per visitor","Experiment learning log"],"channels":["Website","Landing pages","Checkout","Lead forms"],"deliv":["Funnel diagnosis","Hypothesis backlog","Experiment plans","Learning reports"],"who":"Sites with meaningful traffic and unclear results.","outcomes":"Fewer leaks, better decisions, and a record of what you learned.","faqs":[["Do we need lots of traffic?","For formal A/B tests, yes. For structured improvement, no."],["What tools do you use?","GA4, heatmaps and session recordings where consent allows, plus your platform's data."],["How quickly do we see change?","Depends on traffic and the size of the leak; some fixes show fast."],["Will you redesign our site?","Only if the evidence says so."]],"related":["landing-pages","analytics","web-design","paid-advertising"]},{"slug":"marketing-automation","pillar":"automation","name":"Marketing Automation","h":"FOLLOW UP WHILE YOU SLEEP.","problem":"Leads arrive and wait. Follow-up depends on who is free. Nobody knows which enquiry went where.","do":["Email, WhatsApp and CRM workflow planning","Consent-aware follow-up sequences","Segmentation so messages fit the lead","Hand-off rules between marketing and sales","Failure handling: what happens when a message fails","Reporting on speed-to-lead and sequence results"],"track":["Time to first response","Sequence completion and reply rates","Lead stage movement","Failed deliveries caught and resolved"],"channels":["Email","WhatsApp Business API (via approved providers)","CRM (HubSpot, Zoho, others)"],"deliv":["Workflow maps","Sequence copy","Setup & QA","Monitoring checklist"],"who":"Businesses that generate leads faster than they can follow up by hand.","outcomes":"Consistent, timely follow-up that respects consent and reaches a human when needed.","faqs":[["Which CRM?","The one your team will use. We work with the common ones."],["Is WhatsApp automation allowed?","Through official Business API providers with opt-in, yes."],["Will it feel robotic?","Not if written well and handed to humans at the right moment."],["What if a message fails?","We design failure paths, alerts and fallbacks, from the start."]],"related":["analytics","copywriting","landing-pages","linkedin-ads"]},{"slug":"analytics","pillar":"automation","name":"Analytics & Measurement","h":"STOP GUESSING. START TRACKING.","problem":"GA4 installed, nothing configured. Conversions counted twice or not at all. Reports full of numbers, empty of answers.","do":["Event taxonomy, a naming plan everyone understands","GA4 and tag setup where appropriate","Conversion events that reflect business value","Dashboards that answer specific questions","QA of every tag before launch","Consent-aware implementation"],"track":["Conversion accuracy vs. source of truth","Dashboard adoption by your team","Data gaps identified and closed"],"channels":["GA4","Google Tag Manager","Meta / platform pixels","Looker Studio dashboards"],"deliv":["Measurement plan","Tag implementation","Dashboard","QA document"],"who":"Anyone making marketing decisions with numbers they do not fully trust.","outcomes":"Numbers you can defend and dashboards that lead to decisions.","faqs":[["Do you claim a Google or Meta partnership?","No. FODO makes no platform partnership claims."],["Can you fix double-counted conversions?","Usually, it is one of the most common problems."],["Do you build dashboards?","Yes, focused on the questions you actually ask."],["What about consent and privacy?","Tracking respects consent choices; we implement accordingly."]],"related":["cro","paid-advertising","marketing-automation","seo"]}];})(window.FODO_DATA=window.FODO_DATA||{});
